(function(){
  const scenario=window.UxdScenario?window.UxdScenario.get():'default';
  const model=document.getElementById('model'), imageControl=document.getElementById('image-control'), audioControl=document.getElementById('audio-control'), asr=document.getElementById('asr-model'), welcome=document.getElementById('welcome'), body=document.getElementById('chat-body'), alertBox=document.getElementById('persistent-alert');
  let attachment=null, sent=false;
  const capabilities={
    'vision-audio':{name:'Llama 4 Scout · Vision + audio',image:true,audio:true,labels:['Text','Image','Audio']},
    vision:{name:'Llama 3.2 Vision · Vision',image:true,audio:false,labels:['Text','Image']},
    text:{name:'Granite 3.3 8B · Text',image:false,audio:false,labels:['Text']}
  };
  function current(){return capabilities[model.value]||capabilities['vision-audio'];}
  function renderCaps(){const c=current();imageControl.hidden=!c.image;audioControl.hidden=!c.audio;asr.hidden=!c.audio;document.getElementById('capability-list').innerHTML=c.labels.map(x=>'<span class="capability"><i class="dot '+x.toLowerCase()+'"></i>'+x+' input</span>').join('');document.querySelector('.model-meta').innerHTML=c.labels.map(x=>'<span class="pf-v6-c-label '+(x==='Image'?'pf-m-blue':x==='Audio'?'pf-m-purple':'')+'"><span class="pf-v6-c-label__content">'+x+'</span></span>').join('');}
  function notice(text){alertBox.textContent=text;alertBox.hidden=!text;}
  function setScenario(){
    const content=document.getElementById('scenario-content');
    if(scenario==='text-only'){model.value='text';}
    if(scenario==='vision-only'){model.value='vision';}
    renderCaps();
    if(scenario==='audio-no-asr'){asr.innerHTML='<option value="">No transcription model registered</option>';notice('Audio upload is available for this model, but no transcription endpoint is registered. Add an ASR AI Asset to enable audio submission.');}
    if(scenario==='image-response'){
      welcome.hidden=true;content.innerHTML='<div class="message user-message"><div class="message-avatar user-avatar">JD</div><div class="message-inner"><div class="message-name">You <small>Just now</small></div><p>What is happening in this picture?</p><div class="mock-image"><div class="sun"></div><div class="hill hill-back"></div><div class="hill hill-front"></div><div class="image-caption">a sunny mountain landscape</div></div></div></div><div class="message"><div class="message-avatar assistant-avatar">✦</div><div class="message-inner"><div class="message-name">Llama 4 Scout <small>Just now</small></div><p>The image shows a mountain landscape under a clear blue sky. Green hills frame a distant peak, with a small lake in the valley reflecting the sunlight.</p><div class="response-tools"><button>⧉ Copy</button><button>♧ Good response</button></div></div></div>';
    } else if(scenario==='audio-error'||scenario==='silent-audio'){
      welcome.hidden=true;content.innerHTML='<div class="message user-message"><div class="message-avatar user-avatar">JD</div><div class="message-inner"><div class="message-name">You <small>Just now</small></div><p>Summarize this recording for me.</p><div class="audio-chip"><span class="audio-play">▶</span><span><strong>meeting-recording.wav</strong><small>2.4 MB · Audio file</small></span></div></div></div>';
      notice(scenario==='audio-error'?'Transcription failed. Check that your ASR endpoint is available, then try again. No prompt was sent to the selected model.':'No speech was detected in this file. Choose an audio recording with clear speech and try again. No prompt was sent to the selected model.');
    } else if(scenario==='file-too-large'){
      notice('This file is larger than the 10 MB limit. Choose a smaller JPG or PNG. The file was not uploaded.');
    }
  }
  model.addEventListener('change',()=>{renderCaps();notice('');if(attachment&&((attachment.type==='image'&&!current().image)||(attachment.type==='audio'&&!current().audio))){attachment=null;document.getElementById('attachment-preview').hidden=true;}});
  function acceptFile(file,type){if(!file)return;if(file.size===0){notice('This file is empty. Choose a non-empty file and try again.');return;}if(file.size>10*1024*1024){notice('This file is larger than the 10 MB limit. Choose a smaller file. The file was not uploaded.');return;}if(type==='image'&&!['image/jpeg','image/png'].includes(file.type)){notice('Unsupported file type. Choose a JPG or PNG image.');return;}if(type==='audio'&&!['audio/wav','audio/x-wav','audio/mpeg','audio/mp3'].includes(file.type)){notice('Unsupported file type. Choose a WAV or MP3 audio file.');return;}if(!current()[type]){notice('The selected model does not support '+type+' input. Choose a model with this capability.');return;}if(attachment||sent){notice('Only one image or audio file is allowed in a conversation. Start a new chat to attach another file.');return;}attachment={file,type};notice('');const p=document.getElementById('attachment-preview');p.hidden=false;p.innerHTML='<div class="attachment-icon">'+(type==='image'?'▧':'◖')+'</div><div><strong>'+file.name+'</strong><small>'+(file.size/1024/1024).toFixed(1)+' MB · '+(type==='image'?'Image':'Audio file')+'</small></div><button id="remove-attachment" aria-label="Remove attachment">×</button>';document.getElementById('remove-attachment').onclick=()=>{attachment=null;p.hidden=true;};}
  document.getElementById('image-file').addEventListener('change',e=>acceptFile(e.target.files[0],'image'));document.getElementById('audio-file').addEventListener('change',e=>acceptFile(e.target.files[0],'audio'));
  function send(){const text=document.getElementById('prompt').value.trim();if(!text&&!attachment){notice('Enter a prompt or attach a supported file before sending.');return;}if(attachment&&attachment.type==='audio'&&!asr.value){notice('Register a transcription model as an AI Asset before submitting audio.');return;}welcome.hidden=true;const holder=document.getElementById('scenario-content');const file=attachment;holder.innerHTML='<div class="message user-message"><div class="message-avatar user-avatar">JD</div><div class="message-inner"><div class="message-name">You <small>Just now</small></div><p>'+escapeHtml(text||'Please describe this file.')+'</p>'+(file?'<div class="audio-chip"><span class="audio-play">'+(file.type==='image'?'▧':'▶')+'</span><span><strong>'+escapeHtml(file.file.name)+'</strong><small>'+(file.type==='image'?'Image attachment':'Audio file · Ready to transcribe')+'</small></span></div>':'')+'</div></div><div class="message" data-ouia-component-id="assistant-response"><div class="message-avatar assistant-avatar">✦</div><div class="message-inner"><div class="message-name">'+escapeHtml(current().name.split(' · ')[0])+' <small>Just now</small></div><p class="processing">'+(file&&file.type==='audio'?'Transcribing audio, then generating a response...':'Generating response...')+'</p></div></div>';document.getElementById('prompt').value='';document.getElementById('attachment-preview').hidden=true;attachment=null;sent=true;notice('');setTimeout(()=>{const processing=holder.querySelector('.processing');if(processing)processing.textContent=file&&file.type==='audio'?'The audio transcription is ready. The model response would appear here.':'The image is attached to your prompt. The model response would appear here.';},650);}
  function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
  document.getElementById('send').addEventListener('click',send);document.getElementById('prompt').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send();}});document.querySelectorAll('.suggestion').forEach(b=>b.addEventListener('click',()=>document.getElementById('prompt').value=b.dataset.prompt));document.getElementById('new-chat').addEventListener('click',()=>location.href='./index.html');document.getElementById('temperature').addEventListener('input',e=>document.getElementById('temp-value').textContent=e.target.value);
  setScenario();
})();
